import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    lengths = data[1:1 + n]

    total = sum(lengths)

    if total % 2 != 0:
        print("N")
        return

    half = total // 2

    positions = [0] * n
    current = 0
    for i in range(n - 1):
        current += lengths[i]
        positions[i + 1] = current

    position_set = set(positions)

    count = 0
    for p in positions:
        q = p + half
        if q >= total:
            q -= total
        if q in position_set:
            count += 1

    if count // 2 >= 2:
        print("S")
    else:
        print("N")

if __name__ == "__main__":
    main()
